use vstd::prelude::*;

verus! {

fn array_split(a: Vec<i32>) -> (first: Vec<i32>, second: Vec<i32>)
    ensures
        // the two parts together have the same length as the original
        first.len() + second.len() == a.len(),
        // for each index in the original, the same element appears
        // either in the first part (if i < first.len())
        // or in the second part (shifted by first.len())
        forall |i: usize| i < a.len() ==>
            if i < first.len() {
                a[i] == first[i]
            } else {
                a[i] == second[i - first.len()]
            },
        // if the original has length > 1, then each part is strictly shorter
        a.len() > 1 ==> first.len() < a.len() && second.len() < a.len(),
{
    let len = a.len();
    let mid = len / 2;
    let mut first: Vec<i32> = Vec::new();
    let mut second: Vec<i32> = Vec::new();
    let mut idx: usize = 0;
    // We build up first and second by distributing each a[idx]
    // into one of the two vectors.  We maintain:
    //   1) first.len() + second.len() == idx
    //   2) first[0..first.len()] = a[0..first.len()]
    //   3) second[0..second.len()] = a[mid..mid+second.len()]
    while idx < len
        invariant
            idx <= len,
            first.len() + second.len() == idx,
            forall |i: usize| i < first.len() ==> first[i] == a[i],
            forall |j: usize| j < second.len() ==> second[j] == a[mid + j],
        decreases len - idx,
    {
        if idx < mid {
            first.push(a[idx]);
        } else {
            second.push(a[idx]);
        }
        idx += 1;
    }
    (first, second)
}

} // end verus!

